import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxSelect,
  JxButton,
  JxDivider,
  JxAlert,
} from '@jinx-ui/react';

type RegistrationData = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationFormProps = {
  onSubmit: (data: RegistrationData) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const set = (key: keyof RegistrationData) => (value: string) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const contactsFilled = data.name.trim() !== '' && data.email.trim() !== '';
  const addressFilled = data.country !== '' && data.city.trim() !== '';
  const canGoNext = step === 0 ? contactsFilled : addressFilled;

  const summary: Array<[string, string]> = [
    ['Имя', data.name],
    ['Почта', data.email],
    ['Телефон', data.phone || '—'],
    ['Страна', data.country || '—'],
    ['Город', data.city],
    ['Улица, дом', data.street || '—'],
    ['Индекс', data.zip || '—'],
  ];

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (step < steps.length - 1) {
          if (canGoNext) setStep(step + 1);
          return;
        }
        onSubmit(data);
      }}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name')(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email')(event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={(event) => set('phone')(event.target.value)}
            helperText="Необязательно"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={[
              { value: 'Россия', label: 'Россия' },
              { value: 'Казахстан', label: 'Казахстан' },
              { value: 'Армения', label: 'Армения' },
            ]}
            value={data.country}
            onValueChange={set('country')}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city')(event.target.value)}
          />
          <JxInputField
            label="Улица, дом"
            value={data.street}
            onChange={(event) => set('street')(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            inputMode="numeric"
            value={data.zip}
            onChange={(event) => set('zip')(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные">
            После отправки изменить анкету можно будет только через поддержку.
          </JxAlert>
          <dl style={{ display: 'grid', gap: '8px', margin: 0 }}>
            {summary.map(([label, value]) => (
              <div
                key={label}
                style={{ display: 'flex', justifyContent: 'space-between', gap: '16px' }}
              >
                <dt style={{ color: 'var(--jx-text-3)' }}>{label}</dt>
                <dd style={{ margin: 0, textAlign: 'right' }}>{value}</dd>
              </div>
            ))}
          </dl>
        </div>
      )}

      <JxDivider />

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton
          type="button"
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep(step - 1)}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={step < 2 && !canGoNext}>
          {step === steps.length - 1 ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

